(function(){const SIGNAL=61640;window.tuneRealMaterials=function(root,THREE,opts={}){const envInt=opts.envMapIntensity!=null?opts.envMapIntensity:1.35;const floor=opts.minLuma!=null?opts.minLuma:0.04;const seen=new Set;const clones=new Map;root.traverse(o=>{if(!o.isMesh||!o.material)return;const mats=Array.isArray(o.material)?o.material:[o.material];const out=mats.map(m=>{if(!m)return m;if(clones.has(m))return clones.get(m);const mat=m.clone();if("envMapIntensity"in mat)mat.envMapIntensity=envInt;if(mat.color){const c=mat.color;const luma=0.2126*c.r+0.7152*c.g+0.0722*c.b;if(luma<floor){const k=floor/Math.max(luma,1e-5);c.setRGB(Math.min(1,c.r*k||floor),Math.min(1,c.g*k||floor),Math.min(1,c.b*k||floor))}}mat.needsUpdate=true;clones.set(m,mat);seen.add(mat);return mat});o.material=Array.isArray(o.material)?out:out[0]});return seen.size};window.applySolidMaterials=function(root,THREE,spec={}){const color=spec.color!=null?spec.color:1185311;const metalness=spec.metalness!=null?spec.metalness:0.82;const roughness=spec.roughness!=null?spec.roughness:0.34;const envInt=spec.envMapIntensity!=null?spec.envMapIntensity:1.25;const emissive=spec.emissive!=null?spec.emissive:0;const base=new THREE.MeshStandardMaterial({color,metalness,roughness,emissive,emissiveIntensity:spec.emissiveIntensity!=null?spec.emissiveIntensity:1});if("envMapIntensity"in base)base.envMapIntensity=envInt;root.traverse(o=>{if(!o.isMesh)return;o.material=base});return base};void SIGNAL})();
